import{_ as l,c as r,o as a,ag as e}from"./chunks/framework.Bkod66qp.js";const h=JSON.parse('{"title":"임직원 퇴직금 규정","description":"","frontmatter":{"title":"임직원 퇴직금 규정","subtitle":"","doc_id":"","last_update":"2024-02-27","author":"","categories":[],"tags":[]},"headers":[],"relativePath":"regulation/402_임직원 퇴직금 규정(240227).md","filePath":"regulation/402_임직원 퇴직금 규정(240227).md"}'),o={name:"regulation/402_임직원 퇴직금 규정(240227).md"};function d(i,t,n,s,p,g){return a(),r("div",null,t[0]||(t[0]=[e(`<h1 id="law-title" class="center" tabindex="-1">임직원 퇴직금 규정 <a class="header-anchor" href="#law-title" aria-label="Permalink to &quot;임직원 퇴직금 규정 {#law-title .center}&quot;">​</a></h1><div style="text-align:right;"><pre style="display:inline-block;margin:0;white-space:pre;font-family:monospace;">제정 2004.   3.  12
개정 2004.  11.  11
개정 2008.   8.  29
개정 2013.   6.  26
개정 2014.   7.  21
개정 2015.  12.  29
개정 2016.  10.   7
개정 2018.   1.  30
개정 2021.  12.  29
개정 2022.   2.  28
개정 2022.  11.  14
개정 2023.   2.  28
개정 2023.   7.  27
개정 2024.   2.  27</pre></div><h2 id="article1" class="sr-only" tabindex="-1">제1조 (목적) <a class="header-anchor" href="#article1" aria-label="Permalink to &quot;제1조 (목적) {#article1 .sr-only}&quot;">​</a></h2><p><strong>제1조(목적)</strong> 이 규정은 재단법인 서울문화재단(이하 “재단”이라 한다) 보수규정 제23조의 규정에 의하여 재단 임직원의 퇴직금 지급에 관한 사항을 규정함을 목적으로 한다. &lt;개정 2023. 7. 27.&gt;</p><h2 id="article2" class="sr-only" tabindex="-1">제2조 (적용범위) <a class="header-anchor" href="#article2" aria-label="Permalink to &quot;제2조 (적용범위) {#article2 .sr-only}&quot;">​</a></h2><p><strong>제2조(적용범위)</strong> 이 규정은 재단의 임원 및 직원(이하 “임직원”이라 한다)에게 적용한다.</p><h2 id="article3" class="sr-only" tabindex="-1">제3조 (용어의 정의) <a class="header-anchor" href="#article3" aria-label="Permalink to &quot;제3조 (용어의 정의) {#article3 .sr-only}&quot;">​</a></h2><p><strong>제3조(용어의 정의)</strong> 이 규정에서 사용하는 용어의 정의는 다음과 같다.</p><ol><li>“평균임금”이라 함은 근로기준법 제2조의 평균임금을 말한다. &lt;개정 2008. 8. 29.&gt;</li><li>“퇴직금”이라 함은 근속년수에 따라 본 규정 제5조 규정에 의하여 산정한 금액을 일시불을 원칙으로 지급하는 금액을 말한다.</li><li>삭제 &lt;2022. 2. 28.&gt;</li></ol><h2 id="article4" class="sr-only" tabindex="-1">제4조 (지급대상) <a class="header-anchor" href="#article4" aria-label="Permalink to &quot;제4조 (지급대상) {#article4 .sr-only}&quot;">​</a></h2><p><strong>제4조(지급대상)</strong> ① 퇴직금은 재단에서 퇴직당시 계속근로기간이 1년 이상인 임직원에게 퇴직금을 지급한다. &lt;개정 2013. 6. 26.&gt;</p><ol><li><p>의원면직</p></li><li><p>정년퇴직</p></li><li><p>면 직</p></li><li><p>임기만료 퇴직</p></li><li><p>사 망<br> ② 재단은 직원 중 4주간을 평균하여 1주간의 소정근로시간이 15시간 미만인 자에게는 퇴직금을 지급하지 아니한다. &lt;개정 2013. 6. 26.&gt;</p></li></ol><h2 id="article5" class="sr-only" tabindex="-1">제5조 (지급기준) <a class="header-anchor" href="#article5" aria-label="Permalink to &quot;제5조 (지급기준) {#article5 .sr-only}&quot;">​</a></h2><p><strong>제5조(지급기준)</strong> ① 퇴직금액의 산출은 평균임금에 별표 1의 지급률을 곱하여 산출 지급한다. &lt;개정 2013. 6. 26.&gt;<br> ② 삭제 &lt;2013. 6. 26.&gt;</p><h2 id="article6" class="sr-only" tabindex="-1">제6조 (근속년수 계산) <a class="header-anchor" href="#article6" aria-label="Permalink to &quot;제6조 (근속년수 계산) {#article6 .sr-only}&quot;">​</a></h2><p><strong>제6조(근속년수 계산)</strong> ① 근속년수의 계산은 임명된 날로부터 퇴직한 날까지 계산한다. 다만, 고용계약 직원으로서 고용계약기간 만료 후 재고용 될 때에는 계속년수로 산정한다.<br> ② 제1항의 경우 1년 미만의 달수는 월할 계산하고, 월 미만은 일할 계산한다.<br> ③ 시간선택제근무를 하는 직원의 경우, 시간선택제 사용 여부에 관계없이 근로기간 전체를 재직기간에 산입한다.&lt;신설 2015. 12. 29.&gt;, &lt;개정 2023. 2. 28.&gt;<br> ④ 직원의 휴직기간은 계속 근무년수로 산정한다. 다만, 천재지변 또는 전시사변이나 기타의 사유로 인하여 생사 또는 소재 불분명으로 휴직한 기간은 계산에서 제외한다.</p><h2 id="article7" class="sr-only" tabindex="-1">제7조 (퇴직금의 중간정산) <a class="header-anchor" href="#article7" aria-label="Permalink to &quot;제7조 (퇴직금의 중간정산) {#article7 .sr-only}&quot;">​</a></h2><p><strong>제7조(퇴직금의 중간정산)</strong> ① 근로자퇴직급여보장법 제8조제2항에 의거 대통령령으로 정하는 사유가 있는 경우에는 근로자가 퇴직하기 전에 당해 근로자가 계속 근로한 기간에 대한 퇴직금을 미리 정산하여 지급할 수 있다. 이 경우 미리 정산하여 지급한 후의 퇴직금 산정을 위한 계속근로기간은 정산시점부터 새로이 가산한다. &lt;개정 2008. 8. 29., 2013. 6. 26.&gt;<br> ② 삭제 &lt;2013. 6. 26.&gt;<br> ③ 제①항의 퇴직금 중간정산 사유는 다음 각 호의 경우에 한한다. &lt;신설 2013. 6. 26.&gt;</p><ol><li>무주택자인 근로자가 본인명의로 주택을 구입하는 경우</li><li>무주택자인 근로자가 주거를 목적으로 「민법」 제303조에 따른 전세금 또는 「주택임대차보호법」 제3조의2에 따른 보증금을 부담하는 경우(재직기간 중 1회로 한정)</li><li>근로자가 6개월 이상 요양을 필요로 하는 다음 각 목의 어느 하나에 해당하는 사람의 질병이나 부상에 대한 의료비를 해당 근로자가 본인 연간 임금총액의 1천분의 125를 초과하여 부담하는 경우 &lt;개정 2023. 7. 27.&gt;<br> 가. 근로자 본인<br> 나. 근로자의 배우자<br> 다. 근로자 또는 그 배우자의 부양가족</li><li>퇴직금 중간정산을 신청하는 날로부터 역산하여 5년 이내에 가입자가 「채무자회생및파산에관한법률」에 따라 파산선고를 받은 경우</li><li>퇴직금 중간정산을 신청하는 날로부터 역산하여 5년 이내에 가입자가 「채무자회생및파산에관한법률」에 따라 개인회생절차개시결정을 받은 경우</li><li>사용자가 기존의 정년을 연장하거나 보장하는 조건으로 단체협약 및 취업규칙등을 통하여 일정나이, 근속시점 또는 임금액을 기준으로 임금을 줄이는 제도를 시행하는 경우 &lt;개정 2018. 1. 30.&gt;<br> 6의 2. 사용자가 근로자와의 합의에 따라 소정근로시간을 1일 1시간 또는 1주 5시간이상 변경하여 그 변경된 소정근로시간에 따라 근로자가 3개월 이상 계속 근로하기로 한 경우 &lt;개정 2018. 1. 30.&gt;</li><li>그 밖에 천재지변 등으로 피해를 입는 등 고용노동부장관이 정하여 고시하는 사유와 요건에 해당하는 경우</li></ol><h2 id="article8" class="sr-only" tabindex="-1">제8조 (퇴직급여의 지급제한) <a class="header-anchor" href="#article8" aria-label="Permalink to &quot;제8조 (퇴직급여의 지급제한) {#article8 .sr-only}&quot;">​</a></h2><p><strong>제8조(퇴직급여의 지급제한)</strong> ① 삭제 &lt;2013. 6. 26.&gt;<br> ② 형사재판이 계류 중에 있거나 범죄행위로 인하여 수사가 진행 중에 있는 자가 퇴직할 경우에는 형이 확정될 때까지 퇴직금 지급을 보류할 수 있다. 단, 관련 법령에서 정하는 최소한도의 법정퇴직금은 지급한다. &lt;개정 2018. 1. 30.&gt;</p><h2 id="article9" class="sr-only" tabindex="-1">제9조 (퇴직금등의 수령권자) <a class="header-anchor" href="#article9" aria-label="Permalink to &quot;제9조 (퇴직금등의 수령권자) {#article9 .sr-only}&quot;">​</a></h2><p><strong>제9조(퇴직금등의 수령권자)</strong> ① 퇴직금은 본인에게 지급한다. 다만, 퇴직자가 사망한 경우에는 그 유족에게 지급한다. &lt;개정 2022. 2. 28.&gt;<br> ➁ 제1항의 유족범위에 관하여는 근로기준법 시행령 제48조를 준용한다. &lt;개정 2008. 8. 29.&gt;</p><h2 id="article10" class="sr-only" tabindex="-1">제10조 (퇴직금의 지급기한) <a class="header-anchor" href="#article10" aria-label="Permalink to &quot;제10조 (퇴직금의 지급기한) {#article10 .sr-only}&quot;">​</a></h2><p><strong>제10조(퇴직금의 지급기한)</strong> 퇴직금은 퇴직자가 퇴직일로부터 14일 이내에 일시불로 전액을 지급한다. 다만, 특별한 사정이 있을 경우에는 당사자간의 합의에 의하여 3개월까지 지급을 연장할 수 있다. &lt;개정 2013. 6. 26.&gt;</p><h2 id="article11" class="sr-only" tabindex="-1">제11조 (특별공로금) <a class="header-anchor" href="#article11" aria-label="Permalink to &quot;제11조 (특별공로금) {#article11 .sr-only}&quot;">​</a></h2><p><strong>제11조(특별공로금)</strong> 삭제 &lt;2022. 2. 28.&gt;</p><h2 id="article12" class="sr-only" tabindex="-1">제12조 (명예퇴직수당) <a class="header-anchor" href="#article12" aria-label="Permalink to &quot;제12조 (명예퇴직수당) {#article12 .sr-only}&quot;">​</a></h2><p><strong>제12조(명예퇴직수당)</strong> ① 인사규정 제30조의1에 의한 명예퇴직자에게는 별표 3에 정하는 바에 따라 예산의 범위 내에서 퇴직금에 명예퇴직수당을 가산하여 지급한다. &lt;신설 2016. 10. 7.&gt;<br> ② 명예퇴직수당 지급 신청일 현재 다음 각 호의 어느 하나에 해당되는 사람은 명예퇴직수당 지급대상에서 제외한다. &lt;신설 2021. 7. 6.&gt;</p><ol><li>징계의결 요구 중인 자</li><li>징계처분으로 인하여 승진임용 제한기간 중에 있는 자</li><li>형사사건으로 기소 중인 자</li><li>감사기관이나 수사기관에서 비위조사나 수사 중인 자</li><li>임원 승진을 전제로 퇴직하는 자, 임원으로 선임되어 퇴직하는 자</li><li>지방공무원법 제73조제3항에 따라 수사기관의 수사결과가 통보되어 징계의결을 요구해야 하는 자 &lt;신설 2024. 2. 27.&gt;</li><li>감사원 등 관계 행정기관의 장으로부터 징계처분이 요구되어 있는 자 &lt;신설 2024. 2. 27.&gt;</li></ol><h2 id="article13" class="sr-only" tabindex="-1">제13조 (조기퇴직수당) <a class="header-anchor" href="#article13" aria-label="Permalink to &quot;제13조 (조기퇴직수당) {#article13 .sr-only}&quot;">​</a></h2><p><strong>제13조(조기퇴직수당)</strong> ① 인사규정 제30조의2에 의한 조기퇴직자에게는 퇴직당시 기본급의 6개월 범위내의 금액을 퇴직금에 가산하여 지급한다. &lt;신설 2016. 10. 7.&gt;<br> ② 조기퇴직수당 지급 신청일 현재 제12조 2항 각 호의 어느 하나에 해당하는 사람은 조기퇴직수당 지급대상에서 제외한다.&lt;신설 2021. 12. 29.&gt;</p><h2 id="addendum1" class="sr-only" tabindex="-1">부칙 <a class="header-anchor" href="#addendum1" aria-label="Permalink to &quot;부칙 {#addendum1 .sr-only}&quot;">​</a></h2><p><strong>부칙</strong><br> 이 규정은 2004년 3월 12일부터 시행한다.</p><h2 id="addendum2" class="sr-only" tabindex="-1">부칙 <a class="header-anchor" href="#addendum2" aria-label="Permalink to &quot;부칙 {#addendum2 .sr-only}&quot;">​</a></h2><p><strong>부칙</strong> &lt;2004. 11. 11.&gt;<br> 이 규정은 2004년 11월 11일부터 시행한다.</p><h2 id="addendum3" class="sr-only" tabindex="-1">부칙 <a class="header-anchor" href="#addendum3" aria-label="Permalink to &quot;부칙 {#addendum3 .sr-only}&quot;">​</a></h2><p><strong>부칙</strong> &lt;2008. 8. 29.&gt;<br> 이 규정은 2008년 8월 29일부터 시행한다.</p><h2 id="addendum4" class="sr-only" tabindex="-1">부칙 <a class="header-anchor" href="#addendum4" aria-label="Permalink to &quot;부칙 {#addendum4 .sr-only}&quot;">​</a></h2><p><strong>부칙</strong> &lt;2013. 6. 26.&gt;<br> 이 규정은 2013년 6월 26일부터 시행한다.</p><h2 id="addendum5" class="sr-only" tabindex="-1">부칙 <a class="header-anchor" href="#addendum5" aria-label="Permalink to &quot;부칙 {#addendum5 .sr-only}&quot;">​</a></h2><p><strong>부칙</strong> &lt;2015. 12. 29.&gt;<br> 이 규정은 2015년 12월 29일부터 시행한다.</p><h2 id="addendum6" class="sr-only" tabindex="-1">부칙 <a class="header-anchor" href="#addendum6" aria-label="Permalink to &quot;부칙 {#addendum6 .sr-only}&quot;">​</a></h2><p><strong>부칙</strong> &lt;2016. 10. 7.&gt;<br> 이 규정은 2016년 10월 7일부터 시행한다.</p><h2 id="addendum7" class="sr-only" tabindex="-1">부칙 <a class="header-anchor" href="#addendum7" aria-label="Permalink to &quot;부칙 {#addendum7 .sr-only}&quot;">​</a></h2><p><strong>부칙</strong> &lt;2021. 7. 6.&gt;<br> 이 규정은 2021년 7월 6일부터 시행한다.</p><h2 id="addendum8" class="sr-only" tabindex="-1">부칙 <a class="header-anchor" href="#addendum8" aria-label="Permalink to &quot;부칙 {#addendum8 .sr-only}&quot;">​</a></h2><p><strong>부칙</strong> &lt;2021. 12. 29.&gt;<br> 이 규정은 2021년 12월 29일부터 시행한다.</p><h2 id="addendum9" class="sr-only" tabindex="-1">부칙 <a class="header-anchor" href="#addendum9" aria-label="Permalink to &quot;부칙 {#addendum9 .sr-only}&quot;">​</a></h2><p><strong>부칙</strong> &lt;2022. 2. 28.&gt;<br> 이 규정은 2022년 2월 28일부터 시행한다.</p><h2 id="addendum10" class="sr-only" tabindex="-1">부칙 <a class="header-anchor" href="#addendum10" aria-label="Permalink to &quot;부칙 {#addendum10 .sr-only}&quot;">​</a></h2><p><strong>부칙</strong> &lt;2022. 11. 14.&gt;<br> 이 규정은 2022년 11월 14일부터 시행한다.</p><h2 id="addendum11" class="sr-only" tabindex="-1">부칙 <a class="header-anchor" href="#addendum11" aria-label="Permalink to &quot;부칙 {#addendum11 .sr-only}&quot;">​</a></h2><p><strong>부칙</strong> &lt;2023. 2. 28.&gt;<br> 이 규정은 2023년 2월 28일부터 시행한다.</p><h2 id="addendum12" class="sr-only" tabindex="-1">부칙 <a class="header-anchor" href="#addendum12" aria-label="Permalink to &quot;부칙 {#addendum12 .sr-only}&quot;">​</a></h2><p><strong>부칙</strong> &lt;2023. 7. 27.&gt;<br> 이 규정은 2023년 7월 27일부터 시행한다.</p><h2 id="addendum13" class="sr-only" tabindex="-1">부칙 <a class="header-anchor" href="#addendum13" aria-label="Permalink to &quot;부칙 {#addendum13 .sr-only}&quot;">​</a></h2><p><strong>부칙</strong> &lt;2024. 2. 27.&gt;<br> 제1조(시행일) 이 규정은 이사회의 승인을 득한 날로부터 시행한다.</p><p><strong>[별표 1]</strong> &lt;개정 2004. 11. 11., 2008. 8. 29.&gt;</p><p>퇴 직 금 지 급 률 표</p><table style="border-collapse:collapse;border:1px solid #000;width:100%;table-layout:fixed;"><colgroup><col style="width:210px;"><col style="width:387px;"></colgroup><tr><th style="border-top:1px solid #000;border-bottom:1px solid #000;border-left:1px solid #000;padding:2px 4px;vertical-align:middle;border-right:1px solid #000;background-color:#E5E5E5;"><p style="margin:0;text-align:left;">구 분</p></th><th style="border-top:1px solid #000;border-bottom:1px solid #000;border-left:1px solid #000;padding:2px 4px;vertical-align:middle;border-right:1px solid #000;background-color:#E5E5E5;"><p style="margin:0;text-align:left;">지 급 기 준</p></th></tr><tr><td style="border-top:1px solid #000;border-bottom:1px solid #000;border-left:1px solid #000;padding:2px 4px;vertical-align:middle;border-right:1px solid #000;"><p style="margin:0;text-align:left;">임 직 원</p></td><td style="border-top:1px solid #000;border-bottom:1px solid #000;border-left:1px solid #000;padding:2px 4px;vertical-align:middle;border-right:1px solid #000;"><p style="margin:0;text-align:left;">근속년수×평균임금×30일분</p></td></tr></table><p><strong>[별표 2]</strong> &lt;2023. 2. 28.&gt; <strong>시간제근무 근속년수 계산표 &lt;신설 2015. 12. 29.&gt;, 삭제</strong></p><p><strong>[별표 3]</strong> &lt;신설 2016. 10. 7.&gt; <strong>, &lt;개정 2024. 2. 27.&gt;</strong></p><p>명예퇴직수당지급액 산정표</p><table style="border-collapse:collapse;border:1px solid #000;width:100%;table-layout:fixed;"><colgroup><col style="width:129px;"><col style="width:487px;"></colgroup><tr><th style="border-top:1px solid #000;border-bottom:1px solid #000;border-left:1px solid #000;padding:2px 4px;vertical-align:middle;border-right:1px solid #000;background-color:#E5E5E5;"><p style="margin:0;text-align:center;">정년잔여기간별</p><p style="margin:0;text-align:center;">대상자</p></th><th style="border-top:1px solid #000;border-bottom:1px solid #000;border-left:1px solid #000;padding:2px 4px;vertical-align:middle;border-right:1px solid #000;"><p style="margin:0;text-align:center;">산정기준</p></th></tr><tr><th style="border-top:1px solid #000;border-bottom:1px solid #000;border-left:1px solid #000;padding:2px 4px;vertical-align:middle;border-right:1px solid #000;background-color:#E5E5E5;"><p style="margin:0;text-align:center;">1년이상 5년</p><p style="margin:0;text-align:center;">이내인 자</p></th><th style="border-top:1px solid #000;border-bottom:1px solid #000;border-left:1px solid #000;padding:2px 4px;vertical-align:middle;border-right:1px solid #000;"><p style="margin:0;text-align:center;">퇴직당시 월기본급여액의 100분의 50 × 정년잔여월수</p></th></tr><tr><td style="border-top:1px solid #000;border-bottom:1px solid #000;border-left:1px solid #000;padding:2px 4px;vertical-align:middle;border-right:1px solid #000;background-color:#E5E5E5;"><p style="margin:0;text-align:center;">5년초과 10년</p><p style="margin:0;text-align:center;">이내인 자</p></td><td style="border-top:1px solid #000;border-bottom:1px solid #000;border-left:1px solid #000;padding:2px 4px;vertical-align:middle;border-right:1px solid #000;"><p style="margin:0;text-align:center;">퇴직당시 월기본급여액의 100분의 50 ×</p><p style="margin:0;text-align:center;">{60 +(정년잔여월수-60)/2}</p></td></tr><tr><td style="border-top:1px solid #000;border-bottom:1px solid #000;border-left:1px solid #000;padding:2px 4px;vertical-align:middle;border-right:1px solid #000;background-color:#E5E5E5;"><p style="margin:0;text-align:center;">10년</p><p style="margin:0;text-align:center;">초과인 자</p></td><td style="border-top:1px solid #000;border-bottom:1px solid #000;border-left:1px solid #000;padding:2px 4px;vertical-align:middle;border-right:1px solid #000;"><p style="margin:0;text-align:center;">정년 잔여기간이 10년인 자의 금액과 동일한 금액</p><p style="margin:0;text-align:center;">(10년을 초과하는 정년 잔여기간에 대하여는 수당을 지급하지 아니한다)</p></td></tr></table><p>※ 수당지급액의 계산에 있어서 정년 잔여기간의 계산은 수당지급 대상자의 퇴직일을 기준으로 하되, 정년잔여기간은 명예퇴직수당지급대상자의 퇴직일의 다음 달 1일을 기준으로 산정한다.</p>`,66)]))}const b=l(o,[["render",d]]);export{h as __pageData,b as default};
